class FortranMFTObject(MFTObject):
    """Fortran object-file target with a Fortran compiler blueprint."""

    def __init__(
        self,
        name,
        *,
        source,
        dependencies=None,
        compiler=None,
        flags=None,
        silent=None,
        configuration=None,
    ):
        super().__init__(
            name,
            source=source,
            dependencies=dependencies,
            silent=silent,
        )
        self._configuration = (
            Configuration.for_backend("fortran")
            if configuration is None
            else configuration.clone()
        )
        if compiler is None:
            compiler = self._configuration.get_nested(
                "executables", "compiler", default="gfortran"
            )
        self._compiler = compiler
        self._flags = [
            *self._configuration.get_nested("flags", "object", default=[]),
            *(flags or []),
            *self._configuration.get_nested(
                "flags", "extra_object", default=[]
            ),
        ]

    def generate(self, *flags):
        summary = self.get_dependency_summary()
        direct_dependencies = list(self.dependencies)
        if not direct_dependencies:
            raise ValueError(
                f"{type(self).__name__} expects one direct source dependency."
            )
        source_files = list(
            direct_dependencies[0].get_compile_input_contributions()
        )
        if len(source_files) != 1:
            raise ValueError(
                f"{type(self).__name__} expects exactly one compile input."
            )
        cmd_flags = [
            *self._flags,
            *flags,
            *summary["compile_flags"],
            self._join_flags(
                self._configuration.get_nested(
                    "prefixes", "include", default="-I"
                ),
                summary["include_dirs"],
            ),
        ]
        cmd_flags = " ".join(flag for flag in cmd_flags if flag)
        yield (
            f"{self._compiler} -c {source_files[0]} -o {self.target_name()}"
            + (f" {cmd_flags}" if cmd_flags else "")
        )

    def get_include_dir_contributions(self):
        objdir = Path(self.target_name()).parent
        if str(objdir) not in ("", "."):
            yield str(objdir)


class FortranMFTSharedLibrary(MFTSharedLibrary):
    """Fortran shared-library target with a Fortran linker blueprint."""

    def __init__(
        self,
        name,
        dependencies=None,
        *,
        linker=None,
        flags=None,
        silent=None,
        configuration=None,
    ):
        super().__init__(name, dependencies=dependencies, silent=silent)
        self._configuration = (
            Configuration.for_backend("fortran")
            if configuration is None
            else configuration.clone()
        )
        if linker is None:
            linker = self._configuration.get_nested(
                "executables", "linker", default="gfortran"
            )
        self._linker = linker
        self._flags = [
            *self._configuration.get_nested("flags", "shared", default=[]),
            *(flags or []),
            *self._configuration.get_nested(
                "flags", "extra_shared", default=[]
            ),
        ]

    def generate(self, *flags):
        summary = self.get_dependency_summary()
        link_inputs = " ".join(summary["link_inputs"])
        cmd_flags = [
            *self._flags,
            *flags,
            *summary["link_flags"],
            self._join_flags(
                self._configuration.get_nested(
                    "prefixes", "library", default="-L"
                ),
                summary["library_dirs"],
            ),
        ]
        cmd_flags = " ".join(flag for flag in cmd_flags if flag)
        yield (
            f"{self._linker} -o {self.target_name()} {link_inputs}"
            + (f" {cmd_flags}" if cmd_flags else "")
        )


class FortranMFTPythonModule(MFTSpecial):
    """`f2py`-based Python extension target for generated Fortran code."""

    def __init__(
        self,
        name,
        *,
        source,
        module_name,
        output_dir,
        dependencies=None,
        f2py_command=None,
        python_command=None,
        silent=None,
        configuration=None,
    ):
        dependencies = [source, *(dependencies or [])]
        super().__init__(name, dependencies=dependencies, silent=silent)
        self._module_name = module_name
        self._output_dir = output_dir
        self._configuration = (
            Configuration.for_backend("fortran")
            if configuration is None
            else configuration.clone()
        )
        self._f2py_command = f2py_command or self._default_f2py_command()
        self._python_command = python_command or self._configuration.get_nested(
            "executables", "python", default="python3"
        )

    def _default_f2py_command(self):
        configured = os.environ.get(
            "F2PYEXEC"
        ) or self._configuration.get_nested("executables", "f2py", default=None)
        if configured:
            return shlex.quote(configured)
        executable_path = Path(sys.executable).resolve()
        for candidate_name in ("f2py", "f2py3"):
            candidate = executable_path.with_name(candidate_name)
            if candidate.exists():
                return shlex.quote(str(candidate))
        return f"{shlex.quote(sys.executable)} -m {shlex.quote('numpy.f2py')}"

    def generate(self, *flags):
        summary = self.get_dependency_summary()
        direct_dependencies = list(self.dependencies)
        if not direct_dependencies:
            raise ValueError(
                f"{type(self).__name__} expects one direct source dependency."
            )
        source_files = list(
            direct_dependencies[0].get_compile_input_contributions()
        )
        if len(source_files) != 1:
            raise ValueError(
                f"{type(self).__name__} expects exactly one compile input."
            )
        source_name = Path(source_files[0]).name
        compile_flags = [
            *self._configuration.get_nested(
                "flags", "f2py_compile", default=[]
            ),
            *summary["compile_flags"],
            *self._configuration.get_nested(
                "flags", "extra_f2py_compile", default=[]
            ),
            *flags,
        ]
        link_flags = [*summary["link_flags"]]
        include_flags = self._join_flags("-I", summary["include_dirs"])
        library_flags = self._join_flags("-L", summary["library_dirs"])
        link_inputs = " ".join(summary["link_inputs"])
        env_parts = []
        if compile_flags:
            flags_string = " ".join(flag for flag in compile_flags if flag)
            if flags_string:
                env_parts.append(f'FFLAGS="{flags_string} $${{FFLAGS}}"')
                env_parts.append(f'FCFLAGS="{flags_string} $${{FCFLAGS}}"')
        ld_parts = [
            " ".join(flag for flag in link_flags if flag),
            library_flags,
            link_inputs,
        ]
        ldflags_string = " ".join(part for part in ld_parts if part)
        if ldflags_string:
            env_parts.append(f'LDFLAGS="{ldflags_string} $${{LDFLAGS}}"')
        quoted_output_dir = shlex.quote(str(Path(self._output_dir).resolve()))
        module_name = shlex.quote(self._module_name)
        command = [
            f"cd {quoted_output_dir} &&",
            *env_parts,
            self._f2py_command,
            "-c",
            shlex.quote(source_name),
            "-m",
            module_name,
        ]
        if include_flags:
            command.append(include_flags)
        yield " ".join(command)
        yield (
            f"{self._python_command} -c "
            f'"from pathlib import Path; Path({self.target_name()!r}).touch()"'
        )


class FortranNumeric(Numeric):
    """F90 version of a numeric"""


class FortranLibRoutineVariable(LibRoutineVariable):
    """LibRoutineVariable F90 Base class"""

    def get_zero_value(self):
        if self.dtype == "f64":
            return "0.0d0"
        if self.dtype == "f32":
            return "0.0"
        if self.dtype == "i64":
            return "0_8"
        if self.dtype == "i32":
            return "0"
        return "0"

    def get_definition_lines(self) -> str:
        """create the line that defines the variable"""
        dimension_str = ""
        if not self.is_scalar:
            dimension_str = f", dimension({self._size})"
        yield f"{self.lookup_dtype(self._dtype)}{dimension_str} :: {self._name}"

    def lookup_dtype(self, dtype):
        match dtype:
            case "f64":
                return "double precision"
            case "f32":
                return "real"
            case "i64":
                return "integer(8)"
            case "i32":
                return "integer"
        raise ValueError(f"Unknown dtype: {dtype}")

    def at(self, *offsets, **kwargs):
        """Fortran variables start at 1, not 0"""
        return super().at(1, *offsets, **kwargs)

    def expr_at(self, offset_string):
        return f"{self.name}({offset_string})"

    def generate_tozero_lines(self):
        zero_value = self.get_zero_value()
        if self.is_scalar:
            yield f"{self.expr()} = {zero_value}"
            return
        yield f"{self.name}(:) = {zero_value}"


class FortranLocalVariable(FortranLibRoutineVariable, LibRoutineLocalVariable):
    """Local variable, not initialized with intent parameter"""

    def get_definition_lines(self) -> str:
        """create the line that defines the variable"""
        dimension_str = ""
        if not self.is_scalar:
            dimension_str = f", dimension({self._size})"
        yield f"{self.lookup_dtype(self._dtype)}{dimension_str} :: {self._name}"


class FortranDummyVariable(FortranLibRoutineVariable):
    """Dummy variable, used as argument place holder in routines"""

    _intent = None

    def get_definition_lines(self) -> str:
        """create the line that defines the variable"""
        dimension_str = ""
        intent = self.lookup_intent(type(self)._intent)
        intent_str = f", intent({intent})"
        if not self.is_scalar:
            dimension_str = f", dimension({self._size})"
        yield f"{self.lookup_dtype(self._dtype)}{intent_str}{dimension_str} :: {self._name}"

    def lookup_intent(self, intent):
        """lookup the INTENT keyword in definitions"""
        assert intent is not None
        if intent == "RO":
            return "IN"
        if intent == "WO":
            return "OUT"
        if intent == "RW":
            return "INOUT"
        raise ValueError(f"Unknown intent: {intent}")


class FortranInputVariable(FortranDummyVariable, LibRoutineInputVariable):
    """FortranInputVariable, has intent(IN)"""

    _intent = "RO"


class FortranOutputVariable(FortranDummyVariable, LibRoutineOutputVariable):
    """FortranOutputVariable, has intent(OUT)"""

    _intent = "WO"


class FortranInOutVariable(FortranDummyVariable, LibRoutineInOutVariable):
    """FortranInOutVariable, has intent(INOUT)"""

    _intent = "RW"


class FortranBufferVariable(FortranInOutVariable, LibRoutineBufferVariable):
    """Fortran buffer variable with intent(INOUT)."""


class FortranConstant(FortranLibRoutineVariable, LibRoutineConstant):
    """
    Constant is initialized with the parameter keyword in Fortran and its value is set
    upon initialisation
    """

    def get_definition_lines(self) -> str:
        """create the line that defines the variable"""
        # dimension_str = ""
        # if not self.is_scalar:
        #     dimension_str = f", dimension({self._size})"
        if self.is_scalar:
            yield f"{self.lookup_dtype(self._dtype)}, parameter :: {self._name} = {self.value}"
            return
        codeline = f"{self.lookup_dtype(self._dtype)}, parameter :: {self._name}({self.size}) = "
        prefix = "(/"
        suffix = "/)"
        conv = float
        if self.dtype[0] == "i":
            conv = int
        for thisline in multiline_iterable(
            [conv(value) for value in self.values],
            separator=", ",
            max_line_length=100,
            indent="",
            extra_indent="  ",
            linebreak=" &",
            prefix=codeline + prefix,
            suffix=suffix,
            prefix_suffix_lines=False,
        ):
            yield thisline


