class FortranCommentLine(CommentLine):
    """F90 version of CommentLine. Sets comment symbol to !"""

    COMMENT_PREFIX = "! "


class FortranMultiFrameExpandContainer(MultiFrameExpandContainer):
    """F90 version of MultiFrameExpandContainer. In this case, this is a DO-loop."""

    INDENT_BODY = True
    DEFAULT_LOCAL_VARIABLE_CLASS = FortranLocalVariable

    def generate_head_containers(self):
        if self._multiframe_variable is not None:
            yield from self.codelines_from_text(
                f"DO {self._multiframe_variable.expr()} = {self._min_value}, {self._max_value - 1}"
            )

    def generate_foot_containers(self):
        if self._multiframe_variable is not None:
            yield from self.codelines_from_text(
                f"END DO  ! {self._multiframe_variable.expr()}={self._min_value}...{self._max_value - 1}"
            )


class FortranIntCombineExpandContainer(IntCombineExpandContainer):
    """Recombine split integer loop indices for Fortran code emission."""

    INDENT_BODY = True
    DEFAULT_LOCAL_VARIABLE_CLASS = FortranLocalVariable

    def generate_head_containers(self, **_):
        # yield from self.codelines_from_text(
        #     f"! combine {self._variable.local}, {self._first.local} {self._second.local} {self._offset}"
        # )
        yield from self.codelines_from_text(
            f"{self._multiframe_variable.local} = {self._second.local} * {self._first.max_value} + {self._first.local}"
            + (
                f" + {self._multiframe_variable.min_value}"
                if self._multiframe_variable.min_value
                else ""
            )
        )
        yield from self.codelines_from_text(
            f"IF ({self._multiframe_variable.local} .LT. {self._multiframe_variable.max_value}) THEN"
        )

    def generate_foot_containers(self, **_):
        yield from self.codelines_from_text("END IF")


class FortranRoutineContainer(RoutineContainer):
    """F90 version of a RoutineContainer"""

    INDENT_BODY = True
    INPUT_VARIABLE_CLASS = FortranInputVariable

    def generate_head_containers(self, **_):
        call_args = (var.as_argument() for var in self.get_argument_variables())
        yield FortranCommentLine(f"Subroutine: {self.name}", context=self.context)
        yield from self.codelines_from_text(
            f"SUBROUTINE {self.name}({', '.join(call_args)})"
        )

    def generate_foot_containers(self, **_):
        yield from self.codelines_from_text(f"END SUBROUTINE {self.name}")


