class FortranComputeResource(ComputeResource):
    """A compute resource to manage parallel resources and thread-safety features"""

    DEFAULT_LOCAL_VARIABLE_CLASS = FortranLocalVariable

    def create_mfe_container(
        self, *, context, local_variable_capture, loop_capture=None
    ) -> None | MultiFrameExpandContainer:
        return FortranMultiFrameExpandContainer(
            context=context,
            local_variable_capture=local_variable_capture,
        )

    def create_combine_container(
        self, first, second, *, context, local_variable_capture
    ) -> None | MultiFrameExpandContainer:
        return FortranIntCombineExpandContainer(
            first,
            second,
            context=context,
            local_variable_capture=local_variable_capture,
        )


