class FortranLibRoutine(LibRoutine):
    """F90 Version of a LibRoutine, for consinstency"""


class FortranLibrary(Library):
    """F90 Version of a Library"""

    BACKEND_IDENTIFIER = "fortran"
    FILEENDING = "f90"
    INDENTSTR = "  "
    LIBROUTINE_CLASS = FortranLibRoutine
    IMPORTLINE_CLASS = FortranImportContainer
    IMPORTSECTION_CLASS = FortranImportSectionContainer
    DEFAULT_BUILDER = FortranBuilder
    DEFAULT_CONTAINER_CLASS = FortranRoutineContainer

    def __init__(
        self,
        *args,
        resource=None,
        configuration=None,
        general_configuration=None,
        **kwargs,
    ):
        if resource is None:
            resource = FortranComputeResource("FortranResource")
        super().__init__(
            *args,
            resource=resource,
            configuration=configuration,
            general_configuration=general_configuration,
            **kwargs,
        )

    @property
    def objectname(self):
        """Return the default object-file name for this library."""
        return self._get_objectname()

    def _get_objectname(self):
        return f"{self.libname}.o"

    @property
    def sharedlibname(self):
        """Return the default shared-library name for this library."""
        return self._get_sharedlibname()

    def _get_sharedlibname(self):
        return f"lib{self.libname}.so"

    @property
    def modulename(self):
        """Return the Python extension module name for this library."""
        return self._get_modulename()

    def _get_modulename(self):
        return self.libname

    @property
    def modulestampname(self):
        """Return the stamp file used to mark a completed ``f2py`` build."""
        return self._get_modulestampname()

    def _get_modulestampname(self):
        return f"{self.modulename}.f2py.stamp"

    def locate_python_module(self):
        """Return the compiled ``f2py`` extension path if it exists."""
        basepath = Path(self.basepath)
        for pattern in (
            f"{self.modulename}*.so",
            f"{self.modulename}*.pyd",
            f"{self.modulename}*.dll",
        ):
            matches = sorted(basepath.glob(pattern))
            if matches:
                return str(matches[0])
        return None

    def import_python_module(self):
        """Import and return the compiled ``f2py`` extension module."""
        module_path = self.locate_python_module()
        if module_path is None:
            raise ImportError(
                f"no compiled f2py module was found in {Path(self.basepath).resolve()}"
            )
        resolved_module_path = Path(module_path).resolve()
        spec = importlib.util.spec_from_file_location(
            self.modulename,
            resolved_module_path,
        )
        if spec is None or spec.loader is None:
            raise ImportError(
                f"cannot create import spec for {resolved_module_path}"
            )
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        return module

    def generate_head_containers(self, **_):
        """make the enclosings for this container"""
        yield from self.codelines_from_text(f"MODULE {self.libname}")

    def generate_foot_containers(self, **_):
        yield from self.codelines_from_text(f"END MODULE {self.libname}")

    def generate_prmb_containers(self, **_):
        yield from self.codelines_from_text("! IMPORTS")
        yield self.import_capture
        yield from self.codelines_from_text("")
        yield from self.codelines_from_text("IMPLICIT NONE")
        yield from self.codelines_from_text("")
        yield from self.codelines_from_text("! CONSTANTS")
        yield self.definition_capture
        yield from self.codelines_from_text("")
        yield from self.codelines_from_text("CONTAINS")
        yield from self.codelines_from_text("")
        yield from self.codelines_from_text("! ROUTINES")
        yield from self.codelines_from_text("")

    def generate_clsg_containers(self, **_):
        return
        yield

    def get_to_zero_support_routine(self, dtype):
        """Return the external helper routine used to reset one buffer."""
        routine_name = f"phoenix_to_zero_{dtype}"
        existing = self[routine_name]
        if existing is not None:
            return existing
        zero_value = FortranLocalVariable(name="tmp", dtype=dtype, no_entry=True).get_zero_value()
        dtype_name = FortranLocalVariable(name="tmp", dtype=dtype, no_entry=True).lookup_dtype(dtype)
        code = [
            f"SUBROUTINE {routine_name}(buffer, size)",
            f"  {dtype_name}, intent(INOUT), dimension(size) :: buffer",
            "  integer, intent(IN) :: size",
            f"  buffer(:) = {zero_value}",
            f"END SUBROUTINE {routine_name}",
        ]
        return self._register_manual_routine(
            routine_name,
            code=code,
            arguments=[
                {
                    "name": "buffer",
                    "dtype": dtype,
                    "size": 1,
                    "status": "INOUT",
                    "assignment": ("buffer", "data"),
                },
                {
                    "name": "size",
                    "dtype": "i32",
                    "status": "IN",
                },
            ],
        )

    def get_object_target(self):
        """Create the makefile object target for the Fortran source."""
        dependencies = [*self.get_makefile_compile_dependency_targets()]
        return FortranMFTObject(
            self.relative_to_basepath(self.objectname),
            source=self.get_codefile_target(),
            dependencies=dependencies,
            configuration=self.backend_configuration,
        )

    def get_makefile_compile_dependency_targets(self):
        """Yield compile-time Fortran dependencies with module-producing objects."""
        for dependency in self.get_dependencies(recursive=False):
            target = dependency.get_object_target()
            if target is None:
                target = dependency.get_header_target()
            if target is None:
                target = dependency.get_codefile_target()
            if target is not None:
                yield target

    def get_library_target(self):
        """Create the makefile shared-library target for the Fortran source."""
        dependencies = [
            self.get_object_target(),
            *self.get_makefile_dependency_targets(),
        ]
        return FortranMFTSharedLibrary(
            self.relative_to_basepath(self.sharedlibname),
            dependencies=dependencies,
            configuration=self.backend_configuration,
        )

    def get_python_module_target(self):
        """Create the makefile target that builds the ``f2py`` module."""
        dependencies = [*self.get_makefile_compile_dependency_targets()]
        return FortranMFTPythonModule(
            self.relative_to_basepath(self.modulestampname),
            source=self.get_codefile_target(),
            module_name=self.modulename,
            output_dir=self.basepath,
            dependencies=dependencies,
            configuration=self.backend_configuration,
        )

    def get_makefile_targets(self):
        """Yield the source, object, shared-library, and Python-module targets."""
        yield self.get_codefile_target()
        yield self.get_object_target()
        yield self.get_library_target()
        yield self.get_python_module_target()

    def get_execution_target(self):
        """Build the Python extension by default for direct Python usage."""
        if getattr(self, "_is_auxiliary_library", False):
            return self.get_library_target()
        return self.get_python_module_target()

    def get_compilation_output_files(self):
        """Yield all files required for a complete compiled Fortran build."""
        yield self.modulestampname
        module_path = self.locate_python_module()
        if module_path is not None:
            yield module_path
